import { randomUUID } from 'crypto';

/**
 * Object keys for patrol evidence (P1-C). Generated by the server only — a client never supplies or sees a key.
 *
 *   [prefix/]patrol-incoming/{companyId}/{yyyy}/{mm}/{uuid}     where the Guard's presigned PUT lands (transient)
 *   [prefix/]patrol/{companyId}/{yyyy}/{mm}/{uuid}              the verified photo (only the server writes here)
 *   [prefix/]patrol-quarantine/{companyId}/{yyyy}/{mm}/{uuid}   deleted-but-recoverable photos and rejected uploads
 *   [prefix/]patrol-exports/{companyId}/{yyyy}/{mm}/{uuid}.zip  evidence exports (24 h)
 *
 * Tenant-scoped (the company id is the first path element after the area, so a bucket policy or lifecycle rule can be
 * scoped per company), unguessable (a random v4 UUID, 122 bits), and free of personal data (no names, sites, Guards,
 * times of day or file names). The month is the object's creation month, for lifecycle rules and operations only.
 *
 * Separate incoming and verified areas mean a still-valid upload URL can never overwrite a verified photo: the Guard's
 * URL only ever points at patrol-incoming/, and the server copies the bytes it verified into patrol/.
 */

export type PatrolObjectArea = 'incoming' | 'evidence' | 'quarantine' | 'export';

const AREA_SEGMENT: Record<PatrolObjectArea, string> = {
  incoming: 'patrol-incoming',
  evidence: 'patrol',
  quarantine: 'patrol-quarantine',
  export: 'patrol-exports',
};

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}';
export const PATROL_STORAGE_PREFIX_PATTERN = /^[a-z0-9][a-z0-9-]{0,62}$/;
const KEY_PATTERN = new RegExp(
  `^(?:([a-z0-9][a-z0-9-]{0,62})/)?(patrol|patrol-incoming|patrol-quarantine|patrol-exports)/([1-9][0-9]{0,9})/([0-9]{4})/(0[1-9]|1[0-2])/(${UUID})(\\.zip)?$`,
);

export type ParsedPatrolKey = { prefix: string | null; area: PatrolObjectArea; companyId: number; yyyy: string; mm: string; id: string };

export function parsePatrolKey(key: string): ParsedPatrolKey | null {
  const m = KEY_PATTERN.exec(key);
  if (!m) return null;
  const area = (Object.keys(AREA_SEGMENT) as PatrolObjectArea[]).find((a) => AREA_SEGMENT[a] === m[2])!;
  // .zip only (and always) for exports
  if ((area === 'export') !== Boolean(m[7])) return null;
  return { prefix: m[1] ?? null, area, companyId: Number(m[3]), yyyy: m[4], mm: m[5], id: m[6] };
}

export function isPatrolKey(key: string): boolean {
  return parsePatrolKey(key) !== null;
}

export function patrolObjectKey(area: PatrolObjectArea, companyId: number, at: Date, prefix: string | null, id: string = randomUUID()): string {
  if (!Number.isInteger(companyId) || companyId < 1) throw new Error('Invalid company id for an object key');
  const yyyy = String(at.getUTCFullYear()).padStart(4, '0');
  const mm = String(at.getUTCMonth() + 1).padStart(2, '0');
  const key = `${prefix ? `${prefix}/` : ''}${AREA_SEGMENT[area]}/${companyId}/${yyyy}/${mm}/${id}${area === 'export' ? '.zip' : ''}`;
  if (!isPatrolKey(key)) throw new Error('Invalid object key');
  return key;
}

/** The same object id in another area (the verified photo's incoming twin). */
export function siblingKey(key: string, area: Exclude<PatrolObjectArea, 'export'>): string {
  const parsed = parsePatrolKey(key);
  if (!parsed || parsed.area === 'export') throw new Error('Invalid object key');
  return `${parsed.prefix ? `${parsed.prefix}/` : ''}${AREA_SEGMENT[area]}/${parsed.companyId}/${parsed.yyyy}/${parsed.mm}/${parsed.id}`;
}

/** A NEW object id in another area, keeping the company, month and prefix (quarantine copies, restored copies). */
export function freshKeyLike(key: string, area: Exclude<PatrolObjectArea, 'export'>, id: string = randomUUID()): string {
  const parsed = parsePatrolKey(key);
  if (!parsed || parsed.area === 'export') throw new Error('Invalid object key');
  return `${parsed.prefix ? `${parsed.prefix}/` : ''}${AREA_SEGMENT[area]}/${parsed.companyId}/${parsed.yyyy}/${parsed.mm}/${id}`;
}

/** Whether a key belongs to this company (defence in depth: every storage call re-checks it). */
export function keyBelongsTo(key: string, companyId: number): boolean {
  return parsePatrolKey(key)?.companyId === companyId;
}
